    h, w = len(grid), len(grid[0])
    source = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    marker_set = set(marker)
    mr0, mr1 = min(r for r, c in marker), max(r for r, c in marker)
    mc0, mc1 = min(c for r, c in marker), max(c for r, c in marker)
    symmetric_rows = all((mr0 + mr1 - r, c) in marker_set for r, c in marker)
    symmetric_cols = all((r, mc0 + mc1 - c) in marker_set for r, c in marker)
    out = [row[:] for row in grid]
    for r, c in marker:
        out[r][c] = 0
    if symmetric_rows and not symmetric_cols:
        # Marker is a horizontal mirror cue: make the reflected copy below 4.
        edge = max(r for r, c in source)
        for r, c in source:
            rr = 2 * edge + 1 - r
            if rr < h:
                out[rr][c] = 4
    else:
        # Vertical mirror cue. Its horizontal bar points the copy direction:
        # bar at the top -> right; bar at the bottom -> left.
        row_counts = {r: sum((r, c) in marker_set for c in range(w)) for r in range(mr0, mr1 + 1)}
        bar_row = max(row_counts, key=row_counts.get)
        source_left = min(c for r, c in source)
        source_right = max(c for r, c in source)
        if bar_row == mr0:
            edge = source_right
            for r, c in source:
                cc = 2 * edge + 1 - c
                if cc < w:
                    out[r][cc] = 4
        else:
            edge = source_left
            for r, c in source:
                cc = 2 * edge - 1 - c
                if cc >= 0:
                    out[r][cc] = 4
    return out
